Certainly! One of the most common path search algorithms is the Breadth-First Search (BFS). BFS is a simple and effective algorithm for finding the shortest path in an unweighted graph from a start node to a goal node. Here's a Python implementation of BFS:

```python
class Graph:
    def __init__(self, graph_dict=None, directed=True):
        self.graph_dict = graph_dict or {}
        self.directed = directed
        if not directed:
            self.make_undirected()

    def make_undirected(self):
        for a in list(self.graph_dict.keys()):
            for (b, dist) in self.graph_dict[a].items():
                self.graph_dict.setdefault(b, {})[a] = dist

    def connect(self, A, B, distance=1):
        self.graph_dict.setdefault(A, {})[B] = distance
        if not self.directed:
            self.graph_dict.setdefault(B, {})[A] = distance

    def get(self, a, b=None):
        links = self.graph_dict.get(a)
        if b is None:
            return links
        else:
            return links.get(b)

    def nodes(self):
        return list(self.graph_dict.keys())

def bfs(graph, start, goal):
    if goal not in graph.nodes():
        raise ValueError('Invalid goal node')

    # Keep track of visited nodes
    visited = []

    # Keep track of nodes to be checked
    queue = [[start]]

    # If the desired node is the start node, just yield it.
    if start == goal:
        yield [start]
        return

    while queue:
        # Get the last path
        path = queue.pop(0)
        # Get the last node from the path
        node = path[-1]
        # If the node has not been visited
        if node not in visited:
            neighbors = graph.get(node)
            # Go through all neighbor node
            for (n, dist) in neighbors.items():
                # Get the name of the neighbor node
                new_path = list(path)
                new_path.append(n)
                queue.append(new_path)
                # If the neighbor is the goal node
                if n == goal:
                    yield new_path
            # Mark node as visited
            visited.append(node)

def main():
    g = Graph(dict=[
        ('New York', {'Chicago': 250, 'Washington DC': 600}),
        ('Chicago', {'New York': 250, 'Atlanta': 150, 'Washington DC': 150}),
        ('Atlanta', {'Chicago': 150, 'Washington DC': 150, 'Miami': 800}),
        ('Miami', {'Atlanta': 800, 'Washington DC': 500}),
        ('Washington DC', {'New York': 600, 'Chicago': 150, 'Atlanta': 150, 'Miami': 500})
    ])

    # Start BFS search from New York to Washington DC
    bfs_path = list(bfs(g, 'New York', 'Washington DC'))

    print(f'The shortest path from New York to Washington DC: {bfs_path}')

if __name__ == "__main__":
    main()
```

