    # Define the graph
    graph = Graph({
        'A': {'B': 1, 'C': 3, 'D': 7},
        'B': {'A': 1, 'C': 2, 'D': 6},
        'C': {'A': 3, 'B': 2, 'D': 4},
        'D': {'A': 7, 'B': 6, 'C': 4}
    })

    # Check if the graph is connected
    def is_connected(graph, start, goal):
        return any(path for path in dfs(graph, start, goal))

    # Find a path from 'A' to 'D'
    for path in dfs(graph, 'A', 'D'):
        print(f"Path found: {' -> '.join(path)}")

    # Check if we can reach 'D' from 'A'
    if is_connected(graph, 'A', 'D'):
